        offs = off0 + tl.max_contiguous(
            tl.multiple_of(tl.arange(0, BLOCK_SIZE), BLOCK_SIZE), BLOCK_SIZE
        )
        mask = offs < numel
        a = tl.load(A_ptr + offs, mask=mask)
